import{_ as t,a as r,o,a6 as d}from"./chunks/framework.CJDy2q7X.js";const p=JSON.parse(`{"title":"Raise a Return","description":"","frontmatter":{"outline":false,"examples":[{"id":"create-return","title":"Raise a Return","description":"Raise a new return (RMA) request for one item of one of the authenticated customer's orders.","query":"mutation CreateCustomerReturn(\\n  $orderId: Int!\\n  $orderItemId: Int!\\n  $rmaQty: Int!\\n  $resolutionType: String!\\n  $rmaReasonId: Int!\\n  $information: String\\n  $packageCondition: String\\n  $customAttributes: Iterable\\n  $agreement: Boolean!\\n) {\\n  createCustomerReturn(\\n    input: {\\n      orderId: $orderId\\n      orderItemId: $orderItemId\\n      rmaQty: $rmaQty\\n      resolutionType: $resolutionType\\n      rmaReasonId: $rmaReasonId\\n      information: $information\\n      packageCondition: $packageCondition\\n      customAttributes: $customAttributes\\n      agreement: $agreement\\n    }\\n  ) {\\n    customerReturn {\\n      _id\\n      orderId\\n      orderIncrementId\\n      statusId\\n      statusTitle\\n      statusColor\\n      packageCondition\\n      information\\n      canClose\\n      canReopen\\n      isExpired\\n      item\\n      images\\n      customAttributes\\n      messagesCount\\n      createdAt\\n      updatedAt\\n    }\\n  }\\n}\\n","variables":"{\\n  \\"orderId\\": 45,\\n  \\"orderItemId\\": 78,\\n  \\"rmaQty\\": 1,\\n  \\"resolutionType\\": \\"return\\",\\n  \\"rmaReasonId\\": 2,\\n  \\"information\\": \\"Item arrived damaged.\\",\\n  \\"packageCondition\\": \\"open\\",\\n  \\"customAttributes\\": {\\n    \\"1\\": \\"INV-9921\\",\\n    \\"2\\": \\"morning\\"\\n  },\\n  \\"agreement\\": true\\n}\\n","response":"{\\n  \\"data\\": {\\n    \\"createCustomerReturn\\": {\\n      \\"customerReturn\\": {\\n        \\"_id\\": 12,\\n        \\"orderId\\": 45,\\n        \\"orderIncrementId\\": \\"000000045\\",\\n        \\"statusId\\": 1,\\n        \\"statusTitle\\": \\"Pending\\",\\n        \\"statusColor\\": \\"#FDB022\\",\\n        \\"packageCondition\\": \\"open\\",\\n        \\"information\\": \\"Item arrived damaged.\\",\\n        \\"canClose\\": true,\\n        \\"canReopen\\": false,\\n        \\"isExpired\\": false,\\n        \\"item\\": {\\n          \\"id\\": 30,\\n          \\"order_item_id\\": 78,\\n          \\"sku\\": \\"COASTALBREEZEMENSHOODIE\\",\\n          \\"name\\": \\"Coastal Breeze Men's Blue Zipper Hoodie\\",\\n          \\"quantity\\": 1,\\n          \\"resolution\\": \\"return\\",\\n          \\"reason_id\\": 2,\\n          \\"reason\\": \\"Damaged product\\",\\n          \\"variant_id\\": null\\n        },\\n        \\"images\\": [],\\n        \\"customAttributes\\": [\\n          {\\n            \\"field_id\\": 1,\\n            \\"code\\": \\"invoice_number\\",\\n            \\"label\\": \\"Invoice number\\",\\n            \\"type\\": \\"text\\",\\n            \\"value\\": \\"INV-9921\\"\\n          },\\n          {\\n            \\"field_id\\": 2,\\n            \\"code\\": \\"pickup_slot\\",\\n            \\"label\\": \\"Preferred pickup slot\\",\\n            \\"type\\": \\"select\\",\\n            \\"value\\": \\"morning\\"\\n          }\\n        ],\\n        \\"messagesCount\\": 0,\\n        \\"createdAt\\": \\"2026-07-20T10:15:30+00:00\\",\\n        \\"updatedAt\\": \\"2026-07-20T10:15:30+00:00\\"\\n      }\\n    }\\n  }\\n}\\n","commonErrors":[{"error":"item not returnable","cause":"The order item is outside its return window or already fully returned/canceled","solution":"Query returnableItems first and only raise a return for an eligible item and quantity"},{"error":"agreement required","cause":"The agreement field was not set to true","solution":"Send agreement as true to confirm the return terms"},{"error":"The selected item is not eligible for return.","cause":"orderItemId carries a product id instead of the order item id","solution":"Use the orderItemId value from returnableItems — it identifies the order line, not the product"},{"error":"Package condition must be \\"open\\" or \\"packed\\".","cause":"packageCondition holds a value outside the two the storefront offers","solution":"Send open or packed, or omit the field"},{"error":"The field \\":field\\" is required.","cause":"A required custom field was not answered in customAttributes","solution":"Query returnCustomFields and answer every field whose isRequired is true"},{"error":"UNAUTHENTICATED","cause":"Missing or invalid customer Bearer token","solution":"Log in and provide a valid customer authentication token"},{"error":"NOT_FOUND","cause":"The order does not exist or is not owned by the authenticated customer","solution":"Only order IDs belonging to the logged-in customer can be used"}]}]},"headers":[],"relativePath":"api/graphql-api/shop/returns/mutations/create-return.md","filePath":"api/graphql-api/shop/returns/mutations/create-return.md","lastUpdated":1789385991000}`),s={name:"api/graphql-api/shop/returns/mutations/create-return.md"};function n(a,e,i,c,u,l){return o(),r("div",null,e[0]||(e[0]=[d(`<h1 id="raise-a-return" tabindex="-1">Raise a Return <a class="header-anchor" href="#raise-a-return" aria-label="Permalink to &quot;Raise a Return&quot;">​</a></h1><h2 id="about" tabindex="-1">About <a class="header-anchor" href="#about" aria-label="Permalink to &quot;About&quot;">​</a></h2><p>The <code>createCustomerReturn</code> mutation raises a new return (RMA) request for one item of one of the customer&#39;s orders. The item must be return-eligible — check it with <a href="/api/graphql-api/shop/returns/queries/list-returnable-items.html"><code>returnableItems</code></a> first. The requested quantity (<code>rmaQty</code>) is capped server-side by the quantity the customer is actually allowed to return. The return starts in a <code>Pending</code> status.</p><h2 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Authentication&quot;">​</a></h2><p>This mutation requires an authenticated customer — send the storefront key and a customer Bearer token. See the <a href="/api/graphql-api/authentication.html">Authentication</a> page.</p><h2 id="input-fields" tabindex="-1">Input Fields <a class="header-anchor" href="#input-fields" aria-label="Permalink to &quot;Input Fields&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>orderId</code></td><td><code>Int!</code></td><td>✅ Yes</td><td>Id of the order the item belongs to.</td></tr><tr><td><code>orderItemId</code></td><td><code>Int!</code></td><td>✅ Yes</td><td>Id of the <strong>order item</strong> being returned — the <code>orderItemId</code> from <code>returnableItems</code>. This is the order line id, not the product id.</td></tr><tr><td><code>rmaQty</code></td><td><code>Int!</code></td><td>✅ Yes</td><td>Quantity to return. Capped server-side by the returnable quantity.</td></tr><tr><td><code>resolutionType</code></td><td><code>String!</code></td><td>✅ Yes</td><td><code>return</code> or <code>cancel_items</code>.</td></tr><tr><td><code>rmaReasonId</code></td><td><code>Int!</code></td><td>✅ Yes</td><td>Id of the chosen return reason — from <code>returnReasons</code>.</td></tr><tr><td><code>information</code></td><td><code>String</code></td><td>❌ No</td><td>Free-text note about the return.</td></tr><tr><td><code>packageCondition</code></td><td><code>String</code></td><td>❌ No</td><td>Reported package condition — <code>open</code> or <code>packed</code>. Any other value is rejected.</td></tr><tr><td><code>customAttributes</code></td><td><code>Iterable</code></td><td>⚠️ Conditional</td><td>Answers to the return form&#39;s custom fields, keyed by field id — see <a href="/api/graphql-api/shop/returns/queries/list-return-custom-fields.html">List Return Custom Fields</a>. Required when the store has custom fields marked <code>isRequired</code>.</td></tr><tr><td><code>agreement</code></td><td><code>Boolean!</code></td><td>✅ Yes</td><td>Must be <code>true</code> to confirm the return terms.</td></tr></tbody></table><h3 id="custom-fields" tabindex="-1">Custom Fields <a class="header-anchor" href="#custom-fields" aria-label="Permalink to &quot;Custom Fields&quot;">​</a></h3><p>The store can configure additional questions the shopper answers while raising a return. Query them with <a href="/api/graphql-api/shop/returns/queries/list-return-custom-fields.html"><code>returnCustomFields</code></a> and send the answers in <code>customAttributes</code>, keyed by the field <code>_id</code>:</p><ul><li>every field with <code>isRequired: true</code> must be answered, otherwise the mutation is rejected</li><li><code>select</code> and <code>radio</code> answers must be one of the field&#39;s option <code>value</code>s</li><li><code>multiselect</code> and <code>checkbox</code> answers take a list of option values</li><li>the stored answers come back on the return as <code>customAttributes</code></li></ul><h2 id="possible-returns" tabindex="-1">Possible Returns <a class="header-anchor" href="#possible-returns" aria-label="Permalink to &quot;Possible Returns&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>customerReturn._id</code></td><td><code>Int!</code></td><td>Numeric return ID.</td></tr><tr><td><code>customerReturn.orderId</code></td><td><code>Int!</code></td><td>Id of the order the item belongs to.</td></tr><tr><td><code>customerReturn.orderIncrementId</code></td><td><code>String!</code></td><td>Human-readable order number.</td></tr><tr><td><code>customerReturn.statusId</code></td><td><code>Int!</code></td><td>Numeric status id — <code>1</code> (Pending) for a fresh return.</td></tr><tr><td><code>customerReturn.statusTitle</code></td><td><code>String!</code></td><td>Status label.</td></tr><tr><td><code>customerReturn.statusColor</code></td><td><code>String!</code></td><td>Hex color for the status badge.</td></tr><tr><td><code>customerReturn.packageCondition</code></td><td><code>String</code></td><td>Reported package condition.</td></tr><tr><td><code>customerReturn.information</code></td><td><code>String</code></td><td>The note supplied when raising the return.</td></tr><tr><td><code>customerReturn.canClose</code></td><td><code>Boolean</code></td><td>Whether the return can be closed.</td></tr><tr><td><code>customerReturn.canReopen</code></td><td><code>Boolean</code></td><td>Whether the return can be reopened.</td></tr><tr><td><code>customerReturn.isExpired</code></td><td><code>Boolean</code></td><td>Whether the return is past its action window.</td></tr><tr><td><code>customerReturn.item</code></td><td><code>Object</code></td><td>The returned item — <code>id</code>, <code>order_item_id</code>, <code>sku</code>, <code>name</code>, <code>quantity</code>, <code>resolution</code>, <code>reason_id</code>, <code>reason</code>, <code>variant_id</code>. Query bare (a JSON object).</td></tr><tr><td><code>customerReturn.images</code></td><td><code>Array</code></td><td>Attached images (<code>id</code>, <code>path</code>, <code>url</code>). Always empty on a return raised through this mutation — see <a href="#attaching-evidence-photos">Attaching Evidence Photos</a>. Query bare (a JSON array).</td></tr><tr><td><code>customerReturn.customAttributes</code></td><td><code>Array</code></td><td>Answers to the return&#39;s custom fields — <code>field_id</code>, <code>code</code>, <code>label</code>, <code>type</code>, <code>value</code>. Empty when the store has no custom fields. Query bare (a JSON array).</td></tr><tr><td><code>customerReturn.messagesCount</code></td><td><code>Int!</code></td><td>Number of conversation messages — <code>0</code> for a fresh return.</td></tr><tr><td><code>customerReturn.createdAt</code></td><td><code>DateTime!</code></td><td>Return creation timestamp.</td></tr><tr><td><code>customerReturn.updatedAt</code></td><td><code>DateTime!</code></td><td>Return last update timestamp.</td></tr></tbody></table><h2 id="attaching-evidence-photos" tabindex="-1">Attaching Evidence Photos <a class="header-anchor" href="#attaching-evidence-photos" aria-label="Permalink to &quot;Attaching Evidence Photos&quot;">​</a></h2><p>A binary part cannot travel in a JSON GraphQL request, and photos can only go in while the return is being raised — there is no endpoint that adds them afterwards. So when the shopper attached files, raise the whole return over REST instead of through this mutation, sending the same fields as <code>multipart/form-data</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;https://your-store.com/api/shop/returns&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;X-STOREFRONT-KEY: pk_storefront_PvlE42nWGsKRVIf8bDlJngTPAdWAZbIy&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer 438|aSV6JyFn299xuoR6wr5KKOodyIlMA26h0IgHiqLW&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -F</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;order_id=45&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -F</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;order_item_id=78&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -F</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;rma_qty=1&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -F</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;resolution_type=return&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -F</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;rma_reason_id=2&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -F</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;agreement=true&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -F</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;images[]=@/home/john/Pictures/damage-front.jpg&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -F</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;images[]=@/home/john/Pictures/damage-back.jpg&quot;</span></span></code></pre></div><p>Each file is checked against the mime types the store allows (Configuration → Sales → RMA → <em>Allowed file extension</em>). A return raised through this mutation always comes back with <code>images</code> empty, which is why the field reads as empty above rather than missing.</p><p>Files can still reach the store after the fact through the conversation — <a href="/api/graphql-api/shop/returns/mutations/send-return-message.html"><code>createCustomerReturnMessage</code></a> documents the REST call that carries one file per message.</p><h2 id="related-resources" tabindex="-1">Related Resources <a class="header-anchor" href="#related-resources" aria-label="Permalink to &quot;Related Resources&quot;">​</a></h2><ul><li><a href="/api/graphql-api/shop/returns/queries/list-returnable-items.html">List Returnable Items</a></li><li><a href="/api/graphql-api/shop/returns/queries/list-return-reasons.html">List Return Reasons</a></li><li><a href="/api/graphql-api/shop/returns/queries/list-return-custom-fields.html">List Return Custom Fields</a></li><li><a href="/api/graphql-api/shop/returns/mutations/cancel-return.html">Cancel a Return</a></li><li><a href="/api/graphql-api/shop/returns/">Returns Overview</a></li></ul>`,19)]))}const m=t(s,[["render",n]]);export{p as __pageData,m as default};
